#!/usr/bin/env python3
"""Build paper/supplementary.md from the data files (no value typed by hand).
    python3 paper/data/build_si.py"""
import os, json, io, contextlib, runpy
H = os.path.dirname(os.path.abspath(__file__)); P = os.path.join(H, "..")
J = lambda f: json.load(open(os.path.join(H, f), encoding="utf-8"))
REV, LOG, MEAS, LIN = J("review_b01.json"), J("search_log_2026-09-25.json"), J("fig1_measurements.json"), J("lineage_100MPa.json")
LEDGER, S7 = J("screening_ledger_2026-09-25.json"), J("s7_search_2026-09-26.json")
S8 = J("s7_search_2026-09-27_wsl.json"); C8 = S8["_meta"]["counts"]; CH = ", ".join(f"{c['seed'].split()[0]} {c.get('forward',{}).get('n',0)}" for c in S8["citation_chains"])
CAT = {"a": "cites a measurement", "b": "cites another model / blanket citation", "c": "inverse calibration",
       "d": "set or chosen by the authors", "e": "no source given"}
esc = lambda s: str(s).replace("|", "/").replace("\n", " ")
o = ["# Supplementary Information", "", "*Three quantities behind the grain-boundary strength in NMC fracture models*", "",
 "All tables below are generated by `build_si.py` from the data files in the public repository https://github.com/hoseinsepahvand/nmc-gb-strength-data, archived as version 1.0 () at https://doi.org/10.5281/zenodo.23019792 (folder `data/`), which also holds the protocol.", "",
 "## S1. Review protocol", "",
 "The protocol was written and committed before the first search (22 September 2026). Inclusion: a peer-reviewed article or preprint (conference abstracts and theses excluded) that models intergranular or intra-particle interface fracture in a layered-oxide cathode (NMC, NCM, NCA, LiNiO₂, LiCoO₂, Ni-rich) and gives a numeric GB or interface strength, with any symbol. Exclusion: GBs not represented explicitly (homogenised or effective properties, or a single pre-placed cohesive surface); interface fracture energy only, without a strength; core–shell or cathode–electrolyte interfaces; non-layered materials; reviews. Search order: the authors' local library first, then two literature indexes (Firecrawl research index and Scholar Gateway) with at least four query framings each, then citation snowballing from anchor papers.",
 "",
 "Source categories, fixed in advance: (a) cites a specific measurement; (b) cites another modelling paper, or a blanket citation without row-level attribution; (c) inverse calibration or fit to experimental data; (d) the authors state that they set or chose the value; (e) no source given, with the table or text seen; (f) could not be classified because the table or text could not be opened. Category (f) is never counted as (e).",
 "",
 "Deviations, disclosed. (i) Rule D-B01-1 (23 September 2026, after data collection): any statement that the authors themselves set the value, whatever the verb, is category (d); it moved three papers between (b), (d) and (e) and none into or out of (a). (ii) On 24 September 2026 the finite-element model of Wheatcroft et al. 2023 was removed under the pre-registered exclusion for GBs that are not represented explicitly (one cohesive surface on the expected diametral plane of a homogeneous particle). (iii) The protocol required every query string to be logged; the strings of the original searches (21–23 September 2026) were not preserved in the repository. The search was therefore repeated on 25 September 2026 with two openly queryable indexes, Crossref and OpenAlex, and logged in full (Section S2). The repeat found two candidates that had not been screened; both are listed as (f) in Section S3. (iv) On 26 September 2026, after an external audit, M01 (Guichard et al.) was moved from (d) to (c): the source column of its parameter table reads \"Trial and error.\", but the running text states that the peak traction was adjusted to measured indentation data (arXiv:2601.02879, pp. 5-6). The categories themselves were not changed. The resolved record of Li et al. 2025 was moved out of the unresolved list into a separate history field. (v) On 26 September 2026 an internal audit found that three records held as (f) had full texts in hand; read in full, Min & Cho 2018, Allen et al. 2021 and Shen et al. 2024 report no numeric GB strength and were moved to the excluded list, and Zhu X et al. 2020, met only through the 100 MPa citation chain and previously in no list, was added as (f); this extends (f) to a record whose table was seen but to which the inclusion rule could not be applied. The classified twelve did not change. (vi) After a second external audit (26 September 2026) the 272 records of the repeat search were re-screened by title with a recorded decision for each; ten title-level candidates were assessed from web-retrieved text (quotations not yet verified against the PDFs), six were excluded, three are preprints of excluded papers and one (Sun et al. 2016) was added as (f). The classified twelve again did not change.",
 "",
 "Coverage limits. Scopus and Web of Science were not searched, because they were not available to us; the searches used the authors' library, a research-paper index, Crossref, OpenAlex and citation chains (S2, S7, S8). The review is therefore not guaranteed to be exhaustive, and its counts refer only to the records found.", "",
 "Denominator rule (acceptance criterion AC-2 of the protocol, translated from the dated protocol file `protocol/PREREG_B01_review_2026-09-22.md`): pass if n ≥ 15 included papers have a definite category, that is, outside (f); fail if n < 15. If it fails, \"the claim of the paper is downgraded from 'none of the literature' to 'of the N papers whose table we could open, none', and N and the count of category (f) appear in the text of the paper itself. This downgrade is not optional.\" The protocol gives no further rationale for the value 15. The rule failed (n = 12), so every count in the paper is stated for the twelve classifiable models, with the seven in (f) named.",
 "", "## S2. Logged repeat search (" + LOG["date"] + ")", "",
 "| Service | Query | Hits | Hits not screened before |", "|---|---|---|---|"]
for e in LOG["queries"]:
    o.append(f"| {e['service']} | `{e['query']}` | {e['n']} | {sum(1 for h in e['hits'] if h['doi'] and not h['already_screened'])} |")
o += ["", f"All {sum(e['n'] for e in LOG['queries'])} hits, with DOI and title, are in `paper/data/search_log_2026-09-25.json`. The {len(LOG['not_yet_screened'])} unscreened DOIs were screened by title. The first screen recorded only its two positive outcomes; on 26 September 2026 every record was re-screened by title and the decision and reason code of each is in `paper/data/screening_ledger_2026-09-25.json` (" + ", ".join(f"{k} {v}" for k, v in LEDGER["_meta"]["counts"]["by_decision"].items()) + "). The re-screen found 10 title-level candidates beyond the record. Of these, six were excluded, three are preprints of papers already excluded (S3.2, duplicates) and one is (f). They were first assessed from web-retrieved text and re-read on 27 September 2026 from the PDF, the PMC full text or the OSTI abstract, and the quotations in their S3 records are checked against that text. There are two exceptions: the repository copy of Xia et al. 2018 could not be retrieved, and Sun et al. 2016 is paywalled, so its quotation in S3.3 comes from a web summary of the abstract and is not verified. Four hits without a DOI are recorded in the same file under `doi_less_records`, with a stable identifier and a decision each (" + ", ".join(f"{k} {v}" for k, v in LEDGER["_meta"]["counts"]["doi_less"].items()) + "; the duplicate is Guichard et al. 2026).", "",
      "## S3. Screening results", "", f"### S3.1 Classified models (n = {len(REV['included'])})", "",
      "Each record gives the paper, its DOI, the value, the category, and the source statement as quoted from the paper.", ""]
for r in REV["included"]:
    o += [f"**{r['id']}.** {esc(r['cite'])}. DOI {r.get('doi','')}. Value {r['value_MPa']:g} MPa; category: {CAT[r['category']]}.", "",
          f"> {esc(r['source_verbatim'])}", ""]
o += ["", f"### S3.2 Excluded with a stated reason ({len(REV['excluded'])})", "", ""]
for i, r in enumerate(REV["excluded"], 1):
    o += [f"**X{i}.** {esc(r['cite'])}. DOI {r.get('doi','') or 'none'}. Reason: {esc(r['reason'])}", ""]
un = [u for u in REV["unresolved_f"] if not str(u.get("blocker", "")).startswith("RESOLVED")]
o += ["", "Preprint versions of papers already excluded, found in the title re-screen and not counted again: " + "; ".join(f"{d['cite']} ({d['doi']})" for d in REV.get("duplicates_of_screened", [])) + "."]
o += ["", f"### S3.3 Could not be classified, category (f) ({len(un)})", "", ""]
for i, u in enumerate(un, 1):
    o += [f"**F{i}.** {esc(u['cite'])}. DOI {u.get('doi','')}. Why it matters: {esc(u.get('why',''))} Why it could not be classified: {esc(u['blocker'])}", ""]
o += ["", "## S4. Measured strengths plotted in Fig. 1", "", "Values as stored in `paper/data/fig1_measurements.json` (the file also holds the verbatim statements and page anchors).", "",
      "| Series | Source | Mean [MPa] | ± as reported [MPa] | Normalisation |", "|---|---|---|---|---|"] + \
     [f"| {esc(r['label'])} | {esc(r.get('short', r['cite']))} | {', '.join(f'{v:g}' for v in r['means_MPa']) if 'means_MPa' in r else format(r['mean_MPa'], 'g')} | {r['sd_MPa'] if r.get('sd_MPa') is not None else 'not given'} | {esc(r['norm'])} |" for r in MEAS["particle_compression"] + MEAS["particle_tip_indentation"]] + \
     ["", f"Micro-tensile ({esc(MEAS['micro_tensile']['cite'])}): single tests {', '.join(f'{v:g}' for v in MEAS['micro_tensile']['individual_MPa'])} MPa; two-parameter Weibull fit reported by the authors: σ_ch = " + f"{MEAS['micro_tensile']['weibull']['sigma_ch_MPa']:g} MPa, m = {MEAS['micro_tensile']['weibull']['m']:g}, n = {MEAS['micro_tensile']['weibull']['n']}.", "",
      "## S5. Citation lineage of the 100 MPa value (Fig. 2)", "", "| From | To | Link |", "|---|---|---|"]
NL = {n["id"]: n["label"].replace(chr(10), ", ") for n in LIN["nodes"]}
KL = {"cites": "explicit citation for the value", "shared_author": "same value, shared author, no citation (inference)", "estimate": "estimated by analogy"}
for e in LIN["edges"]:
    o.append(f"| {NL.get(e['from'], e['from'])} | {NL.get(e['to'], e['to'])} | {KL.get(e['kind'], e['kind'])} |")
o += ["", "Node identifiers: " + "; ".join(f"{n['id']} = {n['label'].replace(chr(10), ' ')}" for n in LIN["nodes"]) + ".", "",
      "## S6. Parameter sets screened in Section 4 (Fig. 3)", "", "Output of `python3 paper/data/lch_audit.py`, reproduced verbatim:", "", "```"]
buf = io.StringIO()
with contextlib.redirect_stdout(buf): runpy.run_path(os.path.join(H, "lch_audit.py"), run_name="__main__")
o += [buf.getvalue().rstrip(), "```", ""]
C7 = S7["_meta"]["counts"]; rel = [u for u in S7["unique_results"] if str(u.get("decision", u.get("screening", ""))).startswith("relevant")]
o += ["## S7. Logged search for boundary-resolved strength measurements", "",
 "The statement that no peak traction resolved by boundary character and lithium state has been measured for NMC rests on (i) the statement of the only micro-tensile study, \"To the knowledge of the authors, currently no grain boundary stiffness and strength data for NMC under uniaxial tensile load is available\" (Sedlatschek et al. 2026, Section 1); (ii) a logged search run on 26 September 2026 and stored with every query string, service, result list and per-result screening decision in `paper/data/s7_search_2026-09-26.json`: " + f"{C7['queries_total']} queries ({C7['queries_ok']} returned results, {C7['queries_failed']} failed with the logged error), {C7['hits_total']} hits, {C7['unique_results']} unique; " + ", ".join(f"{k.replace('_', ' ')} {v}" for k, v in C7["screening"].items()) + "; (iii) forward-citation checks of Sedlatschek et al. 2026, Wheatcroft et al. 2023 and Stallard et al. 2022, incomplete on 26 September because the citation index rate-limited the requests (logged); and (iv) a second run on 27 September 2026 from a different network, stored in `paper/data/s7_search_2026-09-27_wsl.json`: " + f"{C8['queries_total']} queries ({C8['queries_ok']} returned results; Semantic Scholar again refused), full forward-citation lists from OpenAlex for the three papers ({CH}), {C8['hits_total']} hits, {C8['unique_results']} unique; " + ", ".join(f"{k.replace('_', ' ')} {v}" for k, v in C8["screening"].items()) + ". The four models are outside this claim, which concerns measurements, and are not in the pool of the pre-registered review (S1). Services that returned results over the two runs: web search, a research-paper index, Crossref and OpenAlex; Semantic Scholar and two further literature tools could not be used. None of the unique results reports a strength or peak traction for one boundary of known character in a layered-oxide cathode; the relevant but not boundary-resolved results are whole-particle compression, single-crystal micropillar or shear tests, and the micro-tensile study itself. The claim is therefore stated as \"we found no\".", "",
 "Screening of the 272 title-screen records (S2) is in `paper/data/screening_ledger_2026-09-25.json`.", ""]
S8J = J("s8_atomistic_search_2026-09-27.json"); C9 = S8J["_meta"]["counts"]
o += ["## S8. Logged search for atomistic grain-boundary decohesion data", "",
 "Section 5 states that we found no DFT or MD/MLIP calculation of the work of separation, the traction–separation law or the tensile strength of a grain boundary in a layered-oxide cathode. An earlier search of 21 September 2026 was not logged and is not used. The statement rests on a logged search run on 27 September 2026. The raw retrieval is `paper/data/s8_atomistic_search_2026-09-27_raw.json` (script `s8_atomistic_search.py`); `s8_screen.py` deduplicates it, applies the screening decisions and writes `paper/data/s8_atomistic_search_2026-09-27.json`, using the abstract and page notes in `s8_abstract_cache_2026-09-27.json` for the flagged records. " + f"{C9['queries_total']} queries in OpenAlex and Crossref ({C9['queries_ok']} returned results, {C9['hits_from_queries']} hits) and the OpenAlex forward citations of three atomistic papers (" + ", ".join(f"{c['seed']}: {c['returned']} returned of {c['cited_by_reported']} reported" for c in C9["citation_chains"]) + f") give {C9['hits_total']} hits, {C9['unique_record_keys']} unique record keys after identifier-level deduplication and {C9['unique_works']} works after supplementary files and copies of one work are grouped; " + ", ".join(f"{k.replace('_', ' ')} {v}" for k, v in C9["screening"].items()) + ". Screening decisions are recorded per record key (628); the 605 works are the same records with supplementary files and copies of one work grouped. Screening was by title, with the abstract or publisher page for the flagged records. None of the records reports an atomistic decohesion quantity for a grain boundary in a layered-oxide cathode; the atomistic grain-boundary studies among them concern metals, other ceramics or solid electrolytes.",
 "",
 "Four papers were examined outside the result list: " + "; ".join(f"{e['cite']}: {e['reason']}" for e in S8J["also_examined"]) + ".",
 "",
 "Limits: OpenAlex searches return at most 50 results per query here, two of the 111 citations of Min & Cho 2018 reported by OpenAlex were not returned, Semantic Scholar refused requests from our network, screening was by title, and Bian et al. 2026 was assessed from its abstract only. The statement is therefore worded as \"we found no\".", ""]
open(os.path.join(P, "supplementary.md"), "w", encoding="utf-8").write("\n".join(o).replace("pre-registered", "prespecified").replace("paper/data/", "data/").replace("private project notes", "protocol/").replace("python3 data/lch_audit.py", "python3 lch_audit.py") + "\n")
print(f"supplementary.md: {len(REV['included'])} classified, {len(REV['excluded'])} excluded, {len(un)} unresolved, {len(LOG['queries'])} logged queries")
